<?php
require_once 'includes/bootstrap.php';require_once 'includes/config.php';require_once 'includes/parent-auth.php';require_once 'includes/portal-layout.php';
$parent=require_parent();$student=(int)($_GET['student']??0);$child=parent_child($dbh,$parent['id'],$student);$id=(int)($_GET['assessment']??0);$page=portal_page($_GET);
$rows=cbe_rows($dbh,"SELECT a.id,a.Title,a.AssessmentDate,a.MaximumScore,a.UpdationDate PublishedAt,r.Score,r.Evidence,l.Name PerformanceLevel,s.SubjectName,y.AcademicYear,t.TermName,u.FullName Teacher FROM tblassessmentresults r JOIN tblassessments a ON a.id=r.AssessmentId AND a.Status='published' JOIN tblsubjects s ON s.id=a.SubjectId JOIN tblacademicyears y ON y.id=a.AcademicYearId JOIN tblterms t ON t.id=a.TermId JOIN tblusers u ON u.id=a.TeacherId LEFT JOIN tblperformancelevels l ON l.id=r.PerformanceLevelId WHERE r.StudentId=? AND (?=0 OR a.id=?) ORDER BY a.AssessmentDate DESC,a.id DESC LIMIT 26 OFFSET ".(($page-1)*25),[$student,$id,$id]);
if($id&&!$rows){http_response_code(404);exit('Assessment unavailable.');}
portal_start('Published assessments');?><p><?= academic_h($child['StudentName'].' · '.$child['RollId']) ?></p><div class="report-actions"><a class="btn btn-default" href="parent-dashboard.php">My children</a> <button class="btn btn-primary" onclick="window.print()">Print / Save PDF</button></div><?php foreach(array_slice($rows,0,25) as $r){?><article class="parent-card"><h2><?= academic_h($r['Title']) ?></h2><p><?= academic_h($r['AcademicYear'].' · '.$r['TermName'].' · '.$r['SubjectName']) ?></p><p>Assessed <?= academic_h($r['AssessmentDate']) ?> · <?= academic_h($r['Teacher']) ?></p><?php if($r['MaximumScore']!==null){?><p><strong>Score:</strong> <?= academic_h($r['Score']) ?> / <?= academic_h($r['MaximumScore']) ?></p><?php }?><p><strong>Performance level:</strong> <?= academic_h($r['PerformanceLevel']??'Not recorded') ?></p><p><?= nl2br(academic_h($r['Evidence'])) ?></p></article><?php }if(!$rows)echo '<p>No assessments have been published yet.</p>';portal_pagination($page,count($rows)>25,['student'=>$student]);portal_end(); ?>
